#include "nori/core.hpp"
#include <stdexcept>
namespace nori {void Core::start(){if(running_)return;settings=store_.load();running_=true;} void Core::stop(){if(!running_)return;if(auth_){auth_->shutdown();auth_.reset();}license.offline();running_=false;} void Core::configure_auth(std::string base,std::unique_ptr<Vault> vault,std::string ca){if(!running_)throw std::runtime_error("core stopped"); if(!vault)throw std::runtime_error("vault required"); if(auth_)throw std::runtime_error("authentication already configured");auth_=std::make_unique<AuthController>(std::move(base),settings,std::move(vault),std::move(ca));} void Core::save(){if(!running_)throw std::runtime_error("core stopped");store_.save(settings);} void Core::reset(){settings=store_.reset();} ViewState Core::state(Screen s)const{if(!running_)return ViewState::Disabled; switch(s){case Screen::Dashboard:return ViewState::Success;case Screen::Settings:return ViewState::Success;case Screen::Messages:case Screen::Advertisements:case Screen::Items:case Screen::Automation:return ViewState::NotConnected;case Screen::Telegram:case Screen::License:return (auth_?auth_->view().state==ConnectionState::Online:license.online())?ViewState::Empty:ViewState::Offline;}return ViewState::Error;}}
